public class InnerCampaignChannelSubtypeConfigFactory(Action<Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig> factoryAction = null) : SubResourceFactory<Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig>
{

    internal InnerCampaignEmailChannelSubtypeConfigFactory EmailFactory { get; set; }

    internal InnerCampaignTelephonyChannelSubtypeConfigFactory TelephonyFactory { get; set; }

    internal InnerCampaignSmsChannelSubtypeConfigFactory SmsFactory { get; set; }

    protected override Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig Create()
    {
        var channelSubtypeConfigResult = CreateChannelSubtypeConfig();
        factoryAction?.Invoke(channelSubtypeConfigResult);

        return channelSubtypeConfigResult;
    }

    private Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig CreateChannelSubtypeConfig()
    {
        var channelSubtypeConfigResult = new Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig();

        return channelSubtypeConfigResult;
    }
    public override void CreateChildren(Humidifier.ConnectCampaignsV2.CampaignTypes.ChannelSubtypeConfig result)
    {
        base.CreateChildren(result);

        result.Email ??= EmailFactory?.Build();
        result.Telephony ??= TelephonyFactory?.Build();
        result.Sms ??= SmsFactory?.Build();
    }

} // End Of Class

